import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.DHmNT4rz.js";const u=JSON.parse('{"title":"SEO Patterns","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"develop/seo.md","filePath":"develop/seo.md","lastUpdated":null}'),l={name:"develop/seo.md"};function r(s,e,c,n,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This page mirrors <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.agents/seo.md" target="_blank" rel="noreferrer"><code>.agents/seo.md</code></a> from the repository. Edit it at the source, not here.</p></div><h1 id="seo-patterns" tabindex="-1">SEO Patterns <a class="header-anchor" href="#seo-patterns" aria-label="Permalink to &quot;SEO Patterns&quot;">​</a></h1><p>Use <code>@saasweave/seo</code> for TanStack Start route <code>head()</code> objects.</p><h2 id="package-boundaries" tabindex="-1">Package Boundaries <a class="header-anchor" href="#package-boundaries" aria-label="Permalink to &quot;Package Boundaries&quot;">​</a></h2><ul><li>Keep <code>packages/seo</code> isolated from <code>packages/env</code>.</li><li>Pass app-specific values from the consuming app.</li><li>Do not expand the package surface casually. Export only what the app actually uses.</li><li>Prefer <code>#@/</code> absolute imports inside <code>packages/seo</code>.</li></ul><h2 id="app-pattern" tabindex="-1">App Pattern <a class="header-anchor" href="#app-pattern" aria-label="Permalink to &quot;App Pattern&quot;">​</a></h2><ul><li>Define one typed site config with <code>satisfies TanStackStartSeoSite</code>.</li><li>Wrap <code>generateTanStackStartSeo(...)</code> in an app helper like <code>generateAppSeo(...)</code>.</li><li>Inject repo-specific locale defaults in the app wrapper, not in the package.</li><li>Keep favicon, sitemap, stylesheet, and preload links in the app shell.</li></ul><h2 id="route-pattern" tabindex="-1">Route Pattern <a class="header-anchor" href="#route-pattern" aria-label="Permalink to &quot;Route Pattern&quot;">​</a></h2><ul><li>Use route <code>head()</code> for page SEO, following TanStack Start docs.</li><li>Pass a route-relative <code>canonicalPath</code> such as <code>&quot;/articles&quot;</code> or <code>`/profile/${params.id}`</code>.</li><li>Pass <code>locale</code> from route params when building alternates.</li><li>Use <code>loaderData</code> for dynamic titles, descriptions, and images.</li><li>Use <code>robots: { index: false, follow: false }</code> for dashboards, auth pages, editors, and internal search pages.</li></ul><h2 id="root-route" tabindex="-1">Root Route <a class="header-anchor" href="#root-route" aria-label="Permalink to &quot;Root Route&quot;">​</a></h2><ul><li>Use the same <code>generateAppSeo(...)</code> helper in <code>__root.tsx</code>.</li><li>Only set <code>includeDocumentMeta: true</code> at the root.</li><li>Do not rely on Next.js-style metadata inheritance. TanStack Start route heads are explicit per route.</li></ul><h2 id="titles-and-images" tabindex="-1">Titles And Images <a class="header-anchor" href="#titles-and-images" aria-label="Permalink to &quot;Titles And Images&quot;">​</a></h2><ul><li>Prefer a site-level <code>titleTemplate</code> and let routes pass short page titles.</li><li>Provide a site-level default Open Graph image in the app wrapper.</li><li>Override <code>images</code> only when a route has a better page-specific image.</li></ul><h2 id="json-ld" tabindex="-1">JSON-LD <a class="header-anchor" href="#json-ld" aria-label="Permalink to &quot;JSON-LD&quot;">​</a></h2><ul><li>The package can carry <code>application/ld+json</code> scripts, but it does not build schema objects for you.</li><li>Keep schema generation explicit in the consuming app until there is a clear shared abstraction worth extracting.</li></ul><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>This package does not generate <code>robots.txt</code> or <code>sitemap.xml</code>.</li><li>This package does not fetch data or infer locale automatically.</li><li>Wrong <code>baseUrl</code>, <code>canonicalPath</code>, or locale inputs will produce wrong SEO output.</li></ul>',17)])])}const m=a(l,[["render",r]]);export{u as __pageData,m as default};
